  j constant jsonb := $j$[
{"id":"29266312-c55c-4b82-8434-840b43749b9f","recipe_group_id":"6d159756-ebed-4d34-ac3f-fc0bb31f4750","language":"es","slug":"caldo-de-huevo-changua","public_path":"/caldo-de-huevo-changua","source_url":"https://manualdecocina.com/caldo-de-huevo-changua/","title":"Changua colombiana (caldo de huevo con leche)","excerpt":"Caldo de leche y cebolla larga con huevos escalfados, servido sobre pan tostado y cilantro: la changua colombiana clásica para 4 personas en poco más de 20 minutos.","summary":"La changua es una sopa tradicional de los Andes colombianos, sobre todo de Boyacá, Cundinamarca y Bogotá, que se toma en el desayuno. Se prepara con agua, leche, cebolla larga y huevos escalfados directamente en el caldo, y se sirve sobre pan tostado.\n\nEsta versión usa agua, leche entera y cebolla larga, sin caldo de pollo, y deja las yemas blandas. Rinde 4 raciones y se toma recién hecha.","category":"Sopas y cremas","difficulty":"Fácil","course":"Desayuno","cuisine":"Colombiana","prep_time_minutes":10,"cook_time_minutes":11,"total_time_minutes":21,"servings":4,"keywords":["changua","caldo de huevo","changua colombiana","sopa colombiana","desayuno colombiano","receta de changua"],"ingredients":[{"name":"agua","amount":"500","unit":"ml","group":"Caldo"},{"name":"leche entera","amount":"500","unit":"ml","group":"Caldo"},{"name":"cebolla larga, en rodajas finas","amount":"60","unit":"g","group":"Caldo"},{"name":"sal","amount":"4","unit":"g","group":"Caldo"},{"name":"huevos (4 unidades)","amount":"200","unit":"g","group":"Huevos"},{"name":"pan, en 4 rebanadas tostadas","amount":"120","unit":"g","group":"Para servir"},{"name":"cilantro fresco, picado","amount":"10","unit":"g","group":"Para servir"}],"steps":[{"title":"Corta y tuesta","content":"Pica 60 g de cebolla larga en rodajas finas y 10 g de cilantro. Tuesta 4 rebanadas de pan (120 g) hasta que estén doradas y crujientes, y resérvalas.","image_url":"/recetas/caldo-de-huevo-changua/paso-01.webp","image_alt":"Changua colombiana (caldo de huevo con leche): Corta y tuesta"},{"title":"Hierve el agua con la cebolla","content":"En una olla mediana lleva a ebullición 500 ml de agua con la cebolla larga y 4 g de sal. Cocina 3 minutos a fuego medio.","image_url":"/recetas/caldo-de-huevo-changua/paso-02.webp","image_alt":"Changua colombiana (caldo de huevo con leche): Hierve el agua con la cebolla"},{"title":"Añade la leche","content":"Vierte 500 ml de leche entera y calienta unos 4 minutos a fuego medio, hasta que suelte vapor. No dejes que hierva con fuerza para que la leche no se corte.","image_url":"/recetas/caldo-de-huevo-changua/paso-03.webp","image_alt":"Changua colombiana (caldo de huevo con leche): Añade la leche"},{"title":"Escalfa los huevos","content":"Baja el fuego al mínimo. Rompe los 4 huevos uno a uno en la olla, separados entre sí, tapa y cocina 3–4 minutos, hasta que las claras estén cuajadas y las yemas sigan blandas.","image_url":"/recetas/caldo-de-huevo-changua/paso-04.webp","image_alt":"Changua colombiana (caldo de huevo con leche): Escalfa los huevos"},{"title":"Arma los platos","content":"Coloca una rebanada de pan tostado en cada tazón. Con una espumadera pasa un huevo escalfado sobre el pan y reparte el caldo con leche alrededor.","image_url":"/recetas/caldo-de-huevo-changua/paso-05.webp","image_alt":"Changua colombiana (caldo de huevo con leche): Arma los platos"},{"title":"Termina y sirve","content":"Espolvorea el cilantro picado por encima y sirve de inmediato, mientras la changua esté bien caliente.","image_url":"/recetas/caldo-de-huevo-changua/paso-06.webp","image_alt":"Changua colombiana (caldo de huevo con leche): Termina y sirve"}],"image_url":"/recetas/caldo-de-huevo-changua/portada.webp","gallery":[{"url":"/recetas/caldo-de-huevo-changua/portada.webp","alt":"Changua colombiana (caldo de huevo con leche)"}],"notes":"Los huevos quedan con la yema blanda. Si la sirves a niños pequeños, embarazadas, personas mayores o con defensas bajas, cocina los huevos hasta que la yema esté firme (unos 6 minutos). Mantén el fuego bajo después de añadir la leche: si hierve con fuerza, la leche se corta. La changua se toma recién hecha; si sobra, guárdala en la nevera hasta 1 día y recaliéntala a fuego suave sin hervir, aunque los huevos quedarán más firmes.","nutrition":{"calories":235,"protein_g":13.3,"carbs_g":23,"fat_g":10.0,"sodium_mg":664,"serving_size":"1 ración (1/4 de la receta)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Suma de nutrientes por 100 g multiplicados por los pesos de los ingredientes crudos y divididos entre 4. El agua no se contabiliza. La leche se calcula a 1,03 g/ml (515 g); los 4 huevos, a 200 g.","note":"Estimación por ración con pan blanco de molde (valores del pan sin tostar) y los 4 g de sal indicados; el sodio varía según el pan y la sal que uses.","inputs":[{"fdc_id":"172217","description":"Milk, whole, 3.25% milkfat, without added vitamin A and vitamin D","grams":515,"per100":{"calories":61,"protein_g":3.15,"carbs_g":4.78,"fat_g":3.27,"saturated_fat_g":1.86,"fiber_g":0,"sodium_mg":43}},{"fdc_id":"171287","description":"Egg, whole, raw, fresh","grams":200,"per100":{"calories":143,"protein_g":12.56,"carbs_g":0.72,"fat_g":9.51,"saturated_fat_g":3.126,"fiber_g":0,"sodium_mg":142}},{"fdc_id":"170005","description":"Onions, spring or scallions (includes tops and bulb), raw","grams":60,"per100":{"calories":32,"protein_g":1.83,"carbs_g":7.34,"fat_g":0.19,"saturated_fat_g":0.032,"fiber_g":2.6,"sodium_mg":16}},{"fdc_id":"169997","description":"Coriander (cilantro) leaves, raw","grams":10,"per100":{"calories":23,"protein_g":2.13,"carbs_g":3.67,"fat_g":0.52,"saturated_fat_g":0.014,"fiber_g":2.8,"sodium_mg":46}},{"fdc_id":"174924","description":"Bread, white, commercially prepared (includes soft bread crumbs)","grams":120,"per100":{"calories":266,"protein_g":8.85,"carbs_g":49.4,"fat_g":3.33,"saturated_fat_g":0.7,"fiber_g":2.7,"sodium_mg":490}},{"fdc_id":"173468","description":"Salt, table","grams":4,"per100":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sodium_mg":38758}}]},"seo":{"title":"Changua colombiana (caldo de huevo con leche) | Manual de Cocina","description":"Changua colombiana casera: caldo de leche y cebolla larga con huevos escalfados sobre pan tostado y cilantro. Para 4 personas en 21 minutos.","image_variants":["/recetas/caldo-de-huevo-changua/portada-1x1.webp","/recetas/caldo-de-huevo-changua/portada-4x3.webp","/recetas/caldo-de-huevo-changua/portada-16x9.webp"],"faq":[{"q":"¿Por qué se corta la leche en la changua?","a":"La leche se corta si el caldo hierve con fuerza. Calienta la leche a fuego medio hasta que suelte vapor, sin que rompa a hervir, y baja el fuego al mínimo antes de añadir los huevos."},{"q":"¿Cómo sé si los huevos están en su punto?","a":"Las claras deben verse cuajadas y opacas, y las yemas, blandas al tocarlas con la cuchara. Tapa la olla 3–4 minutos; si prefieres la yema firme, deja 2 o 3 minutos más."},{"q":"¿Puedo usar caldo en lugar de agua?","a":"Sí: el caldo de pollo da más sabor, pero la versión tradicional andina se hace con agua, leche y cebolla larga. Si usas caldo, reduce o elimina la sal."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"1dc31d99-95aa-57db-9522-17eddf0949f4","recipe_group_id":"6d159756-ebed-4d34-ac3f-fc0bb31f4750","language":"de","slug":"changua-kolumbianische-eiersuppe","public_path":"/de/changua-kolumbianische-eiersuppe","source_url":null,"title":"Changua: kolumbianische Eiersuppe mit Milch","excerpt":"Milchsuppe mit Frühlingszwiebeln und pochierten Eiern, serviert auf geröstetem Brot und Koriander: die klassische kolumbianische Changua für 4 Personen in gut 20 Minuten.","summary":"Changua ist eine traditionelle Suppe aus den kolumbianischen Anden, vor allem aus Boyacá, Cundinamarca und Bogotá, die zum Frühstück gegessen wird. Sie wird aus Wasser, Milch, Frühlingszwiebeln und direkt in der Brühe pochierten Eiern zubereitet und auf geröstetem Brot serviert.\n\nDiese Version verwendet Wasser, Vollmilch und Frühlingszwiebeln, ohne Hühnerbrühe, und lässt die Eigelbe weich. Das Rezept ergibt 4 Portionen und wird frisch gegessen.","category":"Suppen und Cremesuppen","difficulty":"Einfach","course":"Frühstück","cuisine":"Kolumbianisch","prep_time_minutes":10,"cook_time_minutes":11,"total_time_minutes":21,"servings":4,"keywords":["Changua","Eiersuppe","kolumbianische Suppe","kolumbianisches Frühstück","Changua Rezept","Suppe mit Milch und Ei"],"ingredients":[{"name":"Wasser","amount":"500","unit":"ml","group":"Brühe"},{"name":"Vollmilch","amount":"500","unit":"ml","group":"Brühe"},{"name":"Frühlingszwiebeln, in feinen Ringen","amount":"60","unit":"g","group":"Brühe"},{"name":"Salz","amount":"4","unit":"g","group":"Brühe"},{"name":"Eier (4 Stück)","amount":"200","unit":"g","group":"Eier"},{"name":"Brot, 4 geröstete Scheiben","amount":"120","unit":"g","group":"Zum Servieren"},{"name":"frischer Koriander, gehackt","amount":"10","unit":"g","group":"Zum Servieren"}],"steps":[{"title":"Schneiden und rösten","content":"60 g Frühlingszwiebeln in feine Ringe schneiden und 10 g Koriander hacken. 4 Scheiben Brot (120 g) rösten, bis sie goldbraun und knusprig sind, und beiseitestellen.","image_url":"/recetas/caldo-de-huevo-changua/paso-01.webp","image_alt":"Changua: kolumbianische Eiersuppe mit Milch: Schneiden und rösten"},{"title":"Wasser mit Zwiebeln aufkochen","content":"In einem mittelgroßen Topf 500 ml Wasser mit den Frühlingszwiebeln und 4 g Salz zum Kochen bringen. 3 Minuten bei mittlerer Hitze garen.","image_url":"/recetas/caldo-de-huevo-changua/paso-02.webp","image_alt":"Changua: kolumbianische Eiersuppe mit Milch: Wasser mit Zwiebeln aufkochen"},{"title":"Milch zugeben","content":"500 ml Vollmilch zugießen und etwa 4 Minuten bei mittlerer Hitze erwärmen, bis Dampf aufsteigt. Nicht stark kochen lassen, damit die Milch nicht ausflockt.","image_url":"/recetas/caldo-de-huevo-changua/paso-03.webp","image_alt":"Changua: kolumbianische Eiersuppe mit Milch: Milch zugeben"},{"title":"Eier pochieren","content":"Die Hitze auf die niedrigste Stufe stellen. Die 4 Eier nacheinander mit etwas Abstand in den Topf schlagen, zudecken und 3–4 Minuten garen, bis das Eiweiß gestockt und das Eigelb noch weich ist.","image_url":"/recetas/caldo-de-huevo-changua/paso-04.webp","image_alt":"Changua: kolumbianische Eiersuppe mit Milch: Eier pochieren"},{"title":"Teller anrichten","content":"Je eine Scheibe geröstetes Brot in jede Schale legen. Mit einem Schaumlöffel ein pochiertes Ei auf das Brot setzen und die Milchbrühe rundherum verteilen.","image_url":"/recetas/caldo-de-huevo-changua/paso-05.webp","image_alt":"Changua: kolumbianische Eiersuppe mit Milch: Teller anrichten"},{"title":"Abschließen und servieren","content":"Mit dem gehackten Koriander bestreuen und sofort servieren, solange die Changua heiß ist.","image_url":"/recetas/caldo-de-huevo-changua/paso-06.webp","image_alt":"Changua: kolumbianische Eiersuppe mit Milch: Abschließen und servieren"}],"image_url":"/recetas/caldo-de-huevo-changua/portada.webp","gallery":[{"url":"/recetas/caldo-de-huevo-changua/portada.webp","alt":"Changua: kolumbianische Eiersuppe mit Milch"}],"notes":"Die Eigelbe bleiben weich. Für kleine Kinder, Schwangere, ältere Menschen oder Personen mit geschwächtem Immunsystem die Eier garen, bis das Eigelb fest ist (etwa 6 Minuten). Nach dem Zugeben der Milch die Hitze niedrig halten: Kocht sie stark, flockt die Milch aus. Changua isst man frisch; Reste im Kühlschrank bis zu 1 Tag aufbewahren und bei schwacher Hitze ohne Kochen erwärmen, die Eier werden dabei fester.","nutrition":{"calories":235,"protein_g":13.3,"carbs_g":23,"fat_g":10.0,"sodium_mg":664,"serving_size":"1 Portion (1/4 des Rezepts)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nährwerte je 100 g, multipliziert mit dem Gewicht der rohen Zutaten und durch 4 geteilt. Wasser wird nicht gezählt. Die Milch wird mit 1,03 g/ml (515 g) gerechnet, die 4 Eier mit 200 g.","note":"Schätzung pro Portion mit weißem Toastbrot (Werte für ungeröstetes Brot) und den angegebenen 4 g Salz; der Natriumgehalt hängt vom verwendeten Brot und Salz ab."},"seo":{"title":"Changua: kolumbianische Eiersuppe mit Milch | Manual de Cocina","description":"Kolumbianische Changua: Milchsuppe mit Frühlingszwiebeln und pochierten Eiern auf geröstetem Brot mit Koriander. Für 4 Personen in 21 Minuten.","image_variants":["/recetas/caldo-de-huevo-changua/portada-1x1.webp","/recetas/caldo-de-huevo-changua/portada-4x3.webp","/recetas/caldo-de-huevo-changua/portada-16x9.webp"],"faq":[{"q":"Warum flockt die Milch in der Changua aus?","a":"Die Milch flockt aus, wenn die Brühe stark kocht. Die Milch bei mittlerer Hitze erwärmen, bis Dampf aufsteigt, ohne sie kochen zu lassen, und vor dem Zugeben der Eier auf die niedrigste Stufe schalten."},{"q":"Woran erkenne ich, dass die Eier gar sind?","a":"Das Eiweiß sollte gestockt und undurchsichtig sein, das Eigelb beim Antippen mit dem Löffel weich. Den Topf 3–4 Minuten zudecken; für ein festes Eigelb 2 bis 3 Minuten länger garen."},{"q":"Kann ich Brühe statt Wasser verwenden?","a":"Ja: Hühnerbrühe gibt mehr Geschmack, aber die traditionelle Andenversion wird mit Wasser, Milch und Frühlingszwiebeln gekocht. Bei Brühe das Salz verringern oder weglassen."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"a5ad8312-3c5f-52bd-99a0-d76fbc265091","recipe_group_id":"6d159756-ebed-4d34-ac3f-fc0bb31f4750","language":"en","slug":"changua-colombian-egg-milk-soup","public_path":"/en/changua-colombian-egg-milk-soup","source_url":null,"title":"Changua: Colombian Egg and Milk Soup","excerpt":"A milk and scallion broth with poached eggs, served over toasted bread and cilantro: the classic Colombian changua for 4 people in just over 20 minutes.","summary":"Changua is a traditional soup from the Colombian Andes, especially Boyacá, Cundinamarca and Bogotá, eaten for breakfast. It is made with water, milk, scallions and eggs poached directly in the broth, and served over toasted bread.\n\nThis version uses water, whole milk and scallions, with no chicken stock, and keeps the yolks soft. It makes 4 servings and is best eaten fresh.","category":"Soups & creams","difficulty":"Easy","course":"Breakfast","cuisine":"Colombian","prep_time_minutes":10,"cook_time_minutes":11,"total_time_minutes":21,"servings":4,"keywords":["changua","Colombian egg soup","egg and milk soup","Colombian breakfast","changua recipe","poached egg soup"],"ingredients":[{"name":"water","amount":"500","unit":"ml","group":"Broth"},{"name":"whole milk","amount":"500","unit":"ml","group":"Broth"},{"name":"scallions, thinly sliced","amount":"60","unit":"g","group":"Broth"},{"name":"salt","amount":"4","unit":"g","group":"Broth"},{"name":"eggs (4)","amount":"200","unit":"g","group":"Eggs"},{"name":"bread, 4 toasted slices","amount":"120","unit":"g","group":"To serve"},{"name":"fresh cilantro, chopped","amount":"10","unit":"g","group":"To serve"}],"steps":[{"title":"Chop and toast","content":"Thinly slice 60 g scallions and chop 10 g cilantro. Toast 4 slices of bread (120 g) until golden and crisp, and set aside.","image_url":"/recetas/caldo-de-huevo-changua/paso-01.webp","image_alt":"Changua: Colombian Egg and Milk Soup: Chop and toast"},{"title":"Boil the water with the scallions","content":"In a medium pot, bring 500 ml water to a boil with the scallions and 4 g salt. Cook 3 minutes over medium heat.","image_url":"/recetas/caldo-de-huevo-changua/paso-02.webp","image_alt":"Changua: Colombian Egg and Milk Soup: Boil the water with the scallions"},{"title":"Add the milk","content":"Pour in 500 ml whole milk and heat about 4 minutes over medium heat, until steaming. Do not let it boil hard, so the milk does not curdle.","image_url":"/recetas/caldo-de-huevo-changua/paso-03.webp","image_alt":"Changua: Colombian Egg and Milk Soup: Add the milk"},{"title":"Poach the eggs","content":"Turn the heat to its lowest setting. Crack the 4 eggs one by one into the pot, spaced apart, cover and cook 3–4 minutes, until the whites are set and the yolks are still soft.","image_url":"/recetas/caldo-de-huevo-changua/paso-04.webp","image_alt":"Changua: Colombian Egg and Milk Soup: Poach the eggs"},{"title":"Assemble the bowls","content":"Place a slice of toasted bread in each bowl. With a slotted spoon, set a poached egg on the bread and ladle the milk broth around it.","image_url":"/recetas/caldo-de-huevo-changua/paso-05.webp","image_alt":"Changua: Colombian Egg and Milk Soup: Assemble the bowls"},{"title":"Finish and serve","content":"Sprinkle with the chopped cilantro and serve immediately, while the changua is piping hot.","image_url":"/recetas/caldo-de-huevo-changua/paso-06.webp","image_alt":"Changua: Colombian Egg and Milk Soup: Finish and serve"}],"image_url":"/recetas/caldo-de-huevo-changua/portada.webp","gallery":[{"url":"/recetas/caldo-de-huevo-changua/portada.webp","alt":"Changua: Colombian Egg and Milk Soup"}],"notes":"The yolks stay soft. If you are serving young children, pregnant women, older adults or anyone with a weakened immune system, cook the eggs until the yolk is firm (about 6 minutes). Keep the heat low after adding the milk: if it boils hard, the milk curdles. Changua is best eaten fresh; leftovers keep in the fridge up to 1 day and can be reheated gently without boiling, though the eggs will firm up.","nutrition":{"calories":235,"protein_g":13.3,"carbs_g":23,"fat_g":10.0,"sodium_mg":664,"serving_size":"1 serving (1/4 of the recipe)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutrients per 100 g multiplied by the weights of the raw ingredients and divided by 4. Water is not counted. Milk is calculated at 1.03 g/ml (515 g) and the 4 eggs at 200 g.","note":"Estimate per serving using sliced white bread (untoasted values) and the 4 g of salt listed; sodium varies with the bread and salt you use."},"seo":{"title":"Changua: Colombian Egg and Milk Soup | Manual de Cocina","description":"Colombian changua: a milk and scallion broth with poached eggs over toasted bread and cilantro. Serves 4 in 21 minutes.","image_variants":["/recetas/caldo-de-huevo-changua/portada-1x1.webp","/recetas/caldo-de-huevo-changua/portada-4x3.webp","/recetas/caldo-de-huevo-changua/portada-16x9.webp"],"faq":[{"q":"Why does the milk curdle in changua?","a":"Milk curdles if the broth boils hard. Heat the milk over medium heat until steaming, without letting it boil, and lower the heat to the minimum before adding the eggs."},{"q":"How do I know the eggs are done?","a":"The whites should look set and opaque, and the yolks should feel soft when touched with a spoon. Cover the pot for 3–4 minutes; for a firm yolk, cook 2 or 3 minutes longer."},{"q":"Can I use stock instead of water?","a":"Yes: chicken stock adds more flavor, but the traditional Andean version is made with water, milk and scallions. If you use stock, reduce or omit the salt."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"0ffa3d54-9d04-52fc-bada-904cca7078f3","recipe_group_id":"6d159756-ebed-4d34-ac3f-fc0bb31f4750","language":"fr","slug":"changua-soupe-colombienne-oeufs-lait","public_path":"/fr/changua-soupe-colombienne-oeufs-lait","source_url":null,"title":"Changua : soupe colombienne aux œufs et au lait","excerpt":"Un bouillon de lait à la ciboule avec des œufs pochés, servi sur du pain grillé et de la coriandre : la changua colombienne classique pour 4 personnes en un peu plus de 20 minutes.","summary":"La changua est une soupe traditionnelle des Andes colombiennes, surtout du Boyacá, du Cundinamarca et de Bogotá, qui se mange au petit-déjeuner. Elle se prépare avec de l’eau, du lait, de la ciboule et des œufs pochés directement dans le bouillon, et se sert sur du pain grillé.\n\nCette version utilise de l’eau, du lait entier et de la ciboule, sans bouillon de poulet, et garde les jaunes coulants. Elle donne 4 portions et se déguste fraîche.","category":"Soupes et crèmes","difficulty":"Facile","course":"Petit-déjeuner","cuisine":"Colombienne","prep_time_minutes":10,"cook_time_minutes":11,"total_time_minutes":21,"servings":4,"keywords":["changua","soupe aux œufs","soupe colombienne","petit-déjeuner colombien","recette de changua","soupe de lait aux œufs pochés"],"ingredients":[{"name":"eau","amount":"500","unit":"ml","group":"Bouillon"},{"name":"lait entier","amount":"500","unit":"ml","group":"Bouillon"},{"name":"ciboule, en fines rondelles","amount":"60","unit":"g","group":"Bouillon"},{"name":"sel","amount":"4","unit":"g","group":"Bouillon"},{"name":"œufs (4)","amount":"200","unit":"g","group":"Œufs"},{"name":"pain, 4 tranches grillées","amount":"120","unit":"g","group":"Pour servir"},{"name":"coriandre fraîche, ciselée","amount":"10","unit":"g","group":"Pour servir"}],"steps":[{"title":"Couper et griller","content":"Coupez 60 g de ciboule en fines rondelles et ciselez 10 g de coriandre. Faites griller 4 tranches de pain (120 g) jusqu’à ce qu’elles soient dorées et croustillantes, et réservez-les.","image_url":"/recetas/caldo-de-huevo-changua/paso-01.webp","image_alt":"Changua : soupe colombienne aux œufs et au lait: Couper et griller"},{"title":"Porter l’eau à ébullition avec la ciboule","content":"Dans une casserole moyenne, portez à ébullition 500 ml d’eau avec la ciboule et 4 g de sel. Laissez cuire 3 minutes à feu moyen.","image_url":"/recetas/caldo-de-huevo-changua/paso-02.webp","image_alt":"Changua : soupe colombienne aux œufs et au lait: Porter l’eau à ébullition avec la ciboule"},{"title":"Ajouter le lait","content":"Versez 500 ml de lait entier et chauffez environ 4 minutes à feu moyen, jusqu’à ce qu’il fume. Ne le laissez pas bouillir fort pour qu’il ne tourne pas.","image_url":"/recetas/caldo-de-huevo-changua/paso-03.webp","image_alt":"Changua : soupe colombienne aux œufs et au lait: Ajouter le lait"},{"title":"Pocher les œufs","content":"Réduisez le feu au minimum. Cassez les 4 œufs un à un dans la casserole, à distance les uns des autres, couvrez et laissez cuire 3 à 4 minutes, jusqu’à ce que les blancs soient pris et les jaunes encore coulants.","image_url":"/recetas/caldo-de-huevo-changua/paso-04.webp","image_alt":"Changua : soupe colombienne aux œufs et au lait: Pocher les œufs"},{"title":"Dresser les bols","content":"Placez une tranche de pain grillé dans chaque bol. À l’aide d’une écumoire, déposez un œuf poché sur le pain et répartissez le bouillon de lait tout autour.","image_url":"/recetas/caldo-de-huevo-changua/paso-05.webp","image_alt":"Changua : soupe colombienne aux œufs et au lait: Dresser les bols"},{"title":"Terminer et servir","content":"Parsemez de coriandre ciselée et servez aussitôt, tant que la changua est bien chaude.","image_url":"/recetas/caldo-de-huevo-changua/paso-06.webp","image_alt":"Changua : soupe colombienne aux œufs et au lait: Terminer et servir"}],"image_url":"/recetas/caldo-de-huevo-changua/portada.webp","gallery":[{"url":"/recetas/caldo-de-huevo-changua/portada.webp","alt":"Changua : soupe colombienne aux œufs et au lait"}],"notes":"Les jaunes restent coulants. Pour de jeunes enfants, des femmes enceintes, des personnes âgées ou fragiles, faites cuire les œufs jusqu’à ce que le jaune soit ferme (environ 6 minutes). Gardez le feu doux après avoir ajouté le lait : s’il bout fort, le lait tourne. La changua se mange fraîche ; les restes se conservent au réfrigérateur jusqu’à 1 jour et se réchauffent doucement sans faire bouillir, mais les œufs seront plus fermes.","nutrition":{"calories":235,"protein_g":13.3,"carbs_g":23,"fat_g":10.0,"sodium_mg":664,"serving_size":"1 portion (1/4 de la recette)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutriments pour 100 g multipliés par le poids des ingrédients crus et divisés par 4. L’eau n’est pas comptée. Le lait est calculé à 1,03 g/ml (515 g) et les 4 œufs à 200 g.","note":"Estimation par portion avec du pain de mie blanc (valeurs du pain non grillé) et les 4 g de sel indiqués ; le sodium varie selon le pain et le sel utilisés."},"seo":{"title":"Changua : soupe colombienne aux œufs et au lait | Manual de Cocina","description":"Changua colombienne : bouillon de lait à la ciboule avec des œufs pochés sur du pain grillé et de la coriandre. Pour 4 personnes en 21 minutes.","image_variants":["/recetas/caldo-de-huevo-changua/portada-1x1.webp","/recetas/caldo-de-huevo-changua/portada-4x3.webp","/recetas/caldo-de-huevo-changua/portada-16x9.webp"],"faq":[{"q":"Pourquoi le lait tourne-t-il dans la changua ?","a":"Le lait tourne si le bouillon bout fort. Chauffez le lait à feu moyen jusqu’à ce qu’il fume, sans le laisser bouillir, et réduisez le feu au minimum avant d’ajouter les œufs."},{"q":"Comment savoir si les œufs sont cuits ?","a":"Les blancs doivent être pris et opaques, et les jaunes encore souples au toucher de la cuillère. Couvrez 3 à 4 minutes ; pour un jaune ferme, comptez 2 ou 3 minutes de plus."},{"q":"Puis-je utiliser du bouillon à la place de l’eau ?","a":"Oui : le bouillon de poulet donne plus de goût, mais la version andine traditionnelle se fait avec de l’eau, du lait et de la ciboule. Avec du bouillon, réduisez ou supprimez le sel."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"41a77b7d-1392-5c28-959f-f0b73516e284","recipe_group_id":"6d159756-ebed-4d34-ac3f-fc0bb31f4750","language":"it","slug":"changua-zuppa-colombiana-uova-latte","public_path":"/it/changua-zuppa-colombiana-uova-latte","source_url":null,"title":"Changua: zuppa colombiana di uova e latte","excerpt":"Un brodo di latte e cipollotto con uova in camicia, servito su pane tostato e coriandolo: la classica changua colombiana per 4 persone in poco più di 20 minuti.","summary":"La changua è una zuppa tradizionale delle Ande colombiane, soprattutto di Boyacá, Cundinamarca e Bogotá, che si mangia a colazione. Si prepara con acqua, latte, cipollotto e uova cotte in camicia direttamente nel brodo, e si serve su pane tostato.\n\nQuesta versione usa acqua, latte intero e cipollotto, senza brodo di pollo, e lascia i tuorli morbidi. Dà 4 porzioni e si gusta appena fatta.","category":"Zuppe e creme","difficulty":"Facile","course":"Colazione","cuisine":"Colombiana","prep_time_minutes":10,"cook_time_minutes":11,"total_time_minutes":21,"servings":4,"keywords":["changua","zuppa di uova","zuppa colombiana","colazione colombiana","ricetta della changua","zuppa di latte e uova"],"ingredients":[{"name":"acqua","amount":"500","unit":"ml","group":"Brodo"},{"name":"latte intero","amount":"500","unit":"ml","group":"Brodo"},{"name":"cipollotto, a rondelle sottili","amount":"60","unit":"g","group":"Brodo"},{"name":"sale","amount":"4","unit":"g","group":"Brodo"},{"name":"uova (4)","amount":"200","unit":"g","group":"Uova"},{"name":"pane, 4 fette tostate","amount":"120","unit":"g","group":"Per servire"},{"name":"coriandolo fresco, tritato","amount":"10","unit":"g","group":"Per servire"}],"steps":[{"title":"Taglia e tosta","content":"Affetta 60 g di cipollotto a rondelle sottili e trita 10 g di coriandolo. Tosta 4 fette di pane (120 g) fino a doratura e croccantezza, e tienile da parte.","image_url":"/recetas/caldo-de-huevo-changua/paso-01.webp","image_alt":"Changua: zuppa colombiana di uova e latte: Taglia e tosta"},{"title":"Porta a bollore l’acqua con il cipollotto","content":"In una pentola media porta a bollore 500 ml di acqua con il cipollotto e 4 g di sale. Cuoci 3 minuti a fuoco medio.","image_url":"/recetas/caldo-de-huevo-changua/paso-02.webp","image_alt":"Changua: zuppa colombiana di uova e latte: Porta a bollore l’acqua con il cipollotto"},{"title":"Aggiungi il latte","content":"Versa 500 ml di latte intero e scalda circa 4 minuti a fuoco medio, finché emette vapore. Non farlo bollire forte, perché il latte non impazzisca.","image_url":"/recetas/caldo-de-huevo-changua/paso-03.webp","image_alt":"Changua: zuppa colombiana di uova e latte: Aggiungi il latte"},{"title":"Cuoci le uova in camicia","content":"Abbassa il fuoco al minimo. Rompi le 4 uova una alla volta nella pentola, distanziate, copri e cuoci 3–4 minuti, finché gli albumi sono rappresi e i tuorli ancora morbidi.","image_url":"/recetas/caldo-de-huevo-changua/paso-04.webp","image_alt":"Changua: zuppa colombiana di uova e latte: Cuoci le uova in camicia"},{"title":"Componi i piatti","content":"Metti una fetta di pane tostato in ogni ciotola. Con una schiumarola appoggia un uovo in camicia sul pane e distribuisci intorno il brodo di latte.","image_url":"/recetas/caldo-de-huevo-changua/paso-05.webp","image_alt":"Changua: zuppa colombiana di uova e latte: Componi i piatti"},{"title":"Termina e servi","content":"Cospargi con il coriandolo tritato e servi subito, finché la changua è ben calda.","image_url":"/recetas/caldo-de-huevo-changua/paso-06.webp","image_alt":"Changua: zuppa colombiana di uova e latte: Termina e servi"}],"image_url":"/recetas/caldo-de-huevo-changua/portada.webp","gallery":[{"url":"/recetas/caldo-de-huevo-changua/portada.webp","alt":"Changua: zuppa colombiana di uova e latte"}],"notes":"I tuorli restano morbidi. Per bambini piccoli, donne in gravidanza, anziani o persone con difese immunitarie basse, cuoci le uova fino a quando il tuorlo è sodo (circa 6 minuti). Dopo aver aggiunto il latte tieni il fuoco basso: se bolle forte, il latte impazzisce. La changua si mangia appena fatta; gli avanzi si conservano in frigorifero fino a 1 giorno e si scaldano piano senza bollire, ma le uova saranno più sode.","nutrition":{"calories":235,"protein_g":13.3,"carbs_g":23,"fat_g":10.0,"sodium_mg":664,"serving_size":"1 porzione (1/4 della ricetta)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutrienti per 100 g moltiplicati per il peso degli ingredienti crudi e divisi per 4. L’acqua non è conteggiata. Il latte è calcolato a 1,03 g/ml (515 g) e le 4 uova a 200 g.","note":"Stima per porzione con pane bianco in cassetta (valori del pane non tostato) e i 4 g di sale indicati; il sodio varia in base al pane e al sale usati."},"seo":{"title":"Changua: zuppa colombiana di uova e latte | Manual de Cocina","description":"Changua colombiana: brodo di latte e cipollotto con uova in camicia su pane tostato e coriandolo. Per 4 persone in 21 minuti.","image_variants":["/recetas/caldo-de-huevo-changua/portada-1x1.webp","/recetas/caldo-de-huevo-changua/portada-4x3.webp","/recetas/caldo-de-huevo-changua/portada-16x9.webp"],"faq":[{"q":"Perché il latte impazzisce nella changua?","a":"Il latte impazzisce se il brodo bolle forte. Scalda il latte a fuoco medio finché emette vapore, senza farlo bollire, e abbassa il fuoco al minimo prima di aggiungere le uova."},{"q":"Come capisco se le uova sono pronte?","a":"Gli albumi devono essere rappresi e opachi e i tuorli morbidi al tocco del cucchiaio. Copri la pentola per 3–4 minuti; per un tuorlo sodo, cuoci 2 o 3 minuti in più."},{"q":"Posso usare il brodo al posto dell’acqua?","a":"Sì: il brodo di pollo dà più sapore, ma la versione andina tradizionale si fa con acqua, latte e cipollotto. Se usi il brodo, riduci o elimina il sale."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"c438cb20-4d7a-540b-9349-48415467e8a5","recipe_group_id":"6d159756-ebed-4d34-ac3f-fc0bb31f4750","language":"ja","slug":"チャングア卵とミルクのスープ","public_path":"/ja/チャングア卵とミルクのスープ","source_url":null,"title":"チャングア：コロンビアの卵とミルクのスープ","excerpt":"ミルクと長ねぎのスープに落とし卵を浮かべ、トーストとコリアンダーを添えます。20分ちょっとで4人分できる、定番のコロンビア風チャングアです。","summary":"チャングアは、コロンビアのアンデス地方（特にボヤカ、クンディナマルカ、ボゴタ）の伝統的なスープで、朝食に食べます。水、牛乳、長ねぎを煮立て、卵をそのままスープの中で半熟に火を通し、トーストにのせていただきます。\n\nこのレシピは鶏のスープを使わず、水と全乳、長ねぎで作り、黄身はとろりと仕上げます。4人分で、できたてがおいしいです。","category":"スープ・ポタージュ","difficulty":"簡単","course":"朝食","cuisine":"コロンビア料理","prep_time_minutes":10,"cook_time_minutes":11,"total_time_minutes":21,"servings":4,"keywords":["チャングア","卵スープ","コロンビア料理","コロンビアの朝食","チャングアの作り方","ミルクと卵のスープ"],"ingredients":[{"name":"水","amount":"500","unit":"ml","group":"スープ"},{"name":"牛乳（全乳）","amount":"500","unit":"ml","group":"スープ"},{"name":"長ねぎ（薄い小口切り）","amount":"60","unit":"g","group":"スープ"},{"name":"塩","amount":"4","unit":"g","group":"スープ"},{"name":"卵（4個）","amount":"200","unit":"g","group":"卵"},{"name":"パン（トースト4枚）","amount":"120","unit":"g","group":"仕上げ"},{"name":"コリアンダー（生・みじん切り）","amount":"10","unit":"g","group":"仕上げ"}],"steps":[{"title":"切ってトーストする","content":"長ねぎ60gを薄い小口切りにし、コリアンダー10gをみじん切りにします。パン4枚（120g）をきつね色にカリッとなるまでトーストし、取っておきます。","image_url":"/recetas/caldo-de-huevo-changua/paso-01.webp","image_alt":"チャングア：コロンビアの卵とミルクのスープ: 切ってトーストする"},{"title":"水と長ねぎを煮立てる","content":"中くらいの鍋に水500ml、長ねぎ、塩4gを入れて沸騰させます。中火で3分煮ます。","image_url":"/recetas/caldo-de-huevo-changua/paso-02.webp","image_alt":"チャングア：コロンビアの卵とミルクのスープ: 水と長ねぎを煮立てる"},{"title":"牛乳を加える","content":"牛乳（全乳）500mlを注ぎ、中火で約4分、湯気が立つまで温めます。牛乳が分離しないよう、強く沸騰させないようにします。","image_url":"/recetas/caldo-de-huevo-changua/paso-03.webp","image_alt":"チャングア：コロンビアの卵とミルクのスープ: 牛乳を加える"},{"title":"卵を落とす","content":"火を最小にします。卵4個を1個ずつ間隔をあけて鍋に割り入れ、ふたをして3〜4分、白身が固まり黄身がまだやわらかいうちに火を通します。","image_url":"/recetas/caldo-de-huevo-changua/paso-04.webp","image_alt":"チャングア：コロンビアの卵とミルクのスープ: 卵を落とす"},{"title":"器に盛る","content":"各器にトーストを1枚ずつ入れます。穴あきおたまで落とし卵をトーストの上にのせ、まわりにミルクスープを注ぎます。","image_url":"/recetas/caldo-de-huevo-changua/paso-05.webp","image_alt":"チャングア：コロンビアの卵とミルクのスープ: 器に盛る"},{"title":"仕上げて出す","content":"みじん切りのコリアンダーを散らし、熱いうちにすぐにいただきます。","image_url":"/recetas/caldo-de-huevo-changua/paso-06.webp","image_alt":"チャングア：コロンビアの卵とミルクのスープ: 仕上げて出す"}],"image_url":"/recetas/caldo-de-huevo-changua/portada.webp","gallery":[{"url":"/recetas/caldo-de-huevo-changua/portada.webp","alt":"チャングア：コロンビアの卵とミルクのスープ"}],"notes":"黄身はやわらかく仕上がります。小さなお子さま、妊娠中の方、高齢の方、免疫力が低下している方に出す場合は、黄身が固まるまで（約6分）火を通してください。牛乳を加えたあとは弱めの火を保ちます。強く沸騰すると牛乳が分離します。チャングアはできたてが一番おいしく、残った場合は冷蔵庫で1日まで保存し、沸騰させずに弱火で温め直してください（卵は固くなります）。","nutrition":{"calories":235,"protein_g":13.3,"carbs_g":23,"fat_g":10.0,"sodium_mg":664,"serving_size":"1人分（レシピの1/4）","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"100gあたりの栄養成分に、生の材料の重量を掛けて合計し、4で割りました。水は含みません。牛乳は1.03g/ml（515g）、卵4個は200gで計算しています。","note":"食パン（トースト前の値）と記載の塩4gを使った1人分の推定値です。ナトリウムは使うパンや塩によって変わります。"},"seo":{"title":"チャングア：コロンビアの卵とミルクのスープ | Manual de Cocina","description":"ミルクと長ねぎのスープに落とし卵を浮かべ、トーストとコリアンダーを添えるコロンビア風チャングア。4人分、21分で作れます。","image_variants":["/recetas/caldo-de-huevo-changua/portada-1x1.webp","/recetas/caldo-de-huevo-changua/portada-4x3.webp","/recetas/caldo-de-huevo-changua/portada-16x9.webp"],"faq":[{"q":"チャングアで牛乳が分離するのはなぜですか？","a":"スープが強く沸騰すると牛乳が分離します。牛乳は中火で湯気が立つまで温め、沸騰させず、卵を入れる前に火を最小にしてください。"},{"q":"卵の火の通り具合はどう見分けますか？","a":"白身が固まって白く不透明になり、黄身はスプーンで触るとやわらかい状態です。ふたをして3〜4分。黄身を固めにしたい場合は、さらに2〜3分加熱してください。"},{"q":"水の代わりにスープストックを使えますか？","a":"はい。鶏のスープを使うと風味が増しますが、アンデス地方の伝統的な作り方は水、牛乳、長ねぎです。スープストックを使う場合は塩を減らすか省いてください。"}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"799da79f-363f-5515-b433-3a487c26dc3b","recipe_group_id":"6d159756-ebed-4d34-ac3f-fc0bb31f4750","language":"pt","slug":"changua-sopa-colombiana-ovos-leite","public_path":"/pt/changua-sopa-colombiana-ovos-leite","source_url":null,"title":"Changua: sopa colombiana de ovos e leite","excerpt":"Caldo de leite e cebolinha com ovos pochê, servido sobre pão torrado e coentro: a clássica changua colombiana para 4 pessoas em pouco mais de 20 minutos.","summary":"A changua é uma sopa tradicional dos Andes colombianos, sobretudo de Boyacá, Cundinamarca e Bogotá, que se toma no café da manhã. É feita com água, leite, cebolinha e ovos pochê cozidos diretamente no caldo, e servida sobre pão torrado.\n\nEsta versão usa água, leite integral e cebolinha, sem caldo de galinha, e mantém as gemas moles. Rende 4 porções e é melhor na hora.","category":"Sopas e cremes","difficulty":"Fácil","course":"Café da manhã","cuisine":"Colombiana","prep_time_minutes":10,"cook_time_minutes":11,"total_time_minutes":21,"servings":4,"keywords":["changua","sopa de ovo","sopa colombiana","café da manhã colombiano","receita de changua","sopa de leite com ovos"],"ingredients":[{"name":"água","amount":"500","unit":"ml","group":"Caldo"},{"name":"leite integral","amount":"500","unit":"ml","group":"Caldo"},{"name":"cebolinha, em rodelas finas","amount":"60","unit":"g","group":"Caldo"},{"name":"sal","amount":"4","unit":"g","group":"Caldo"},{"name":"ovos (4)","amount":"200","unit":"g","group":"Ovos"},{"name":"pão, 4 fatias torradas","amount":"120","unit":"g","group":"Para servir"},{"name":"coentro fresco, picado","amount":"10","unit":"g","group":"Para servir"}],"steps":[{"title":"Corte e toste","content":"Corte 60 g de cebolinha em rodelas finas e pique 10 g de coentro. Toste 4 fatias de pão (120 g) até ficarem douradas e crocantes e reserve.","image_url":"/recetas/caldo-de-huevo-changua/paso-01.webp","image_alt":"Changua: sopa colombiana de ovos e leite: Corte e toste"},{"title":"Ferva a água com a cebolinha","content":"Em uma panela média, leve 500 ml de água ao ponto de fervura com a cebolinha e 4 g de sal. Cozinhe 3 minutos em fogo médio.","image_url":"/recetas/caldo-de-huevo-changua/paso-02.webp","image_alt":"Changua: sopa colombiana de ovos e leite: Ferva a água com a cebolinha"},{"title":"Junte o leite","content":"Despeje 500 ml de leite integral e aqueça cerca de 4 minutos em fogo médio, até soltar vapor. Não deixe ferver forte para o leite não talhar.","image_url":"/recetas/caldo-de-huevo-changua/paso-03.webp","image_alt":"Changua: sopa colombiana de ovos e leite: Junte o leite"},{"title":"Escalfe os ovos","content":"Reduza o fogo ao mínimo. Quebre os 4 ovos um a um na panela, separados entre si, tampe e cozinhe 3–4 minutos, até as claras firmarem e as gemas continuarem moles.","image_url":"/recetas/caldo-de-huevo-changua/paso-04.webp","image_alt":"Changua: sopa colombiana de ovos e leite: Escalfe os ovos"},{"title":"Monte os pratos","content":"Coloque uma fatia de pão torrado em cada tigela. Com uma escumadeira, passe um ovo pochê para cima do pão e distribua o caldo de leite ao redor.","image_url":"/recetas/caldo-de-huevo-changua/paso-05.webp","image_alt":"Changua: sopa colombiana de ovos e leite: Monte os pratos"},{"title":"Finalize e sirva","content":"Salpique o coentro picado e sirva imediatamente, enquanto a changua estiver bem quente.","image_url":"/recetas/caldo-de-huevo-changua/paso-06.webp","image_alt":"Changua: sopa colombiana de ovos e leite: Finalize e sirva"}],"image_url":"/recetas/caldo-de-huevo-changua/portada.webp","gallery":[{"url":"/recetas/caldo-de-huevo-changua/portada.webp","alt":"Changua: sopa colombiana de ovos e leite"}],"notes":"As gemas ficam moles. Se for servir a crianças pequenas, gestantes, idosos ou pessoas com imunidade baixa, cozinhe os ovos até a gema ficar firme (cerca de 6 minutos). Mantenha o fogo baixo depois de juntar o leite: se ferver forte, o leite talha. A changua é melhor na hora; as sobras duram até 1 dia na geladeira e podem ser reaquecidas em fogo baixo, sem ferver, mas os ovos ficarão mais firmes.","nutrition":{"calories":235,"protein_g":13.3,"carbs_g":23,"fat_g":10.0,"sodium_mg":664,"serving_size":"1 porção (1/4 da receita)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutrientes por 100 g multiplicados pelo peso dos ingredientes crus e divididos por 4. A água não é contabilizada. O leite é calculado a 1,03 g/ml (515 g) e os 4 ovos a 200 g.","note":"Estimativa por porção com pão de forma branco (valores do pão sem torrar) e os 4 g de sal indicados; o sódio varia conforme o pão e o sal usados."},"seo":{"title":"Changua: sopa colombiana de ovos e leite | Manual de Cocina","description":"Changua colombiana: caldo de leite e cebolinha com ovos pochê sobre pão torrado e coentro. Para 4 pessoas em 21 minutos.","image_variants":["/recetas/caldo-de-huevo-changua/portada-1x1.webp","/recetas/caldo-de-huevo-changua/portada-4x3.webp","/recetas/caldo-de-huevo-changua/portada-16x9.webp"],"faq":[{"q":"Por que o leite talha na changua?","a":"O leite talha se o caldo ferver forte. Aqueça o leite em fogo médio até soltar vapor, sem deixar ferver, e reduza o fogo ao mínimo antes de juntar os ovos."},{"q":"Como sei se os ovos estão no ponto?","a":"As claras devem estar firmes e opacas, e as gemas, moles ao toque da colher. Tampe a panela por 3–4 minutos; para gema firme, deixe mais 2 ou 3 minutos."},{"q":"Posso usar caldo no lugar da água?","a":"Pode: o caldo de galinha dá mais sabor, mas a versão andina tradicional é feita com água, leite e cebolinha. Se usar caldo, reduza ou elimine o sal."}]},"published":true,"editorial_status":"published","content_html":""}
]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/caldo-de-huevo-changua') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    '', x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;
